/**
 * SpreadsheetML (.xlsx) writer and reader.
 *
 * The writer turns CSV/TSV into a one-sheet workbook: strings are written as
 * inline strings (no shared-string table to keep in sync), numeric-looking
 * cells become numbers, and a field starting with `=` becomes a formula with
 * `fullCalcOnLoad` set so Excel/WPS computes it when the document opens.
 *
 * The reader walks the real package — workbook → relationships → worksheets —
 * and understands shared strings, inline strings, numbers, booleans, formula
 * results and the common date number formats. It returns TSV per sheet, which
 * is what the model can actually reason about on a phone-sized context.
 *
 * Dates are the one place where "raw value" would be actively misleading: a
 * spreadsheet cell showing 2026-11-23 is stored as 46389. The reader maps the
 * style's number format back to ISO text instead of handing the model a number
 * that looks like a quantity.
 */

import { OfficeError } from "./errors.js";
import { readZip, writeZip } from "./zip.js";

const NS_MAIN = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
const NS_R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
const MAX_ROWS = 500;
const MAX_COLS = 50;
const MAX_CELL_CHARS = 500;

export function escapeXml(text) {
	return String(text)
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&apos;");
}

function decodeXml(text) {
	return String(text).replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi, (match, entity) => {
		const lower = entity.toLowerCase();
		if (lower === "amp") return "&";
		if (lower === "lt") return "<";
		if (lower === "gt") return ">";
		if (lower === "quot") return '"';
		if (lower === "apos") return "'";
		if (lower.startsWith("#x")) return String.fromCodePoint(Number.parseInt(lower.slice(2), 16));
		return String.fromCodePoint(Number.parseInt(lower.slice(1), 10));
	});
}

/** Detect the delimiter from the first line, outside quotes. */
export function sniffDelimiter(text) {
	const line = text.split("\n", 1)[0] ?? "";
	let quoted = false;
	const counts = new Map([[",", 0], ["\t", 0], [";", 0]]);
	for (const char of line) {
		if (char === '"') quoted = !quoted;
		else if (!quoted && counts.has(char)) counts.set(char, counts.get(char) + 1);
	}
	let best = ",";
	let bestCount = 0;
	for (const [delimiter, count] of counts) {
		if (count > bestCount) {
			best = delimiter;
			bestCount = count;
		}
	}
	return best;
}

/**
 * Parse CSV/TSV text into rows. Handles quoted fields, `""` escapes, CRLF and
 * newlines inside quotes; a trailing newline does not create an empty row.
 */
export function parseCsv(text, delimiter) {
	const source = String(text ?? "").replace(/\r\n?/g, "\n");
	const sep = delimiter ?? sniffDelimiter(source);
	const rows = [];
	let row = [];
	let field = "";
	let quoted = false;
	for (let index = 0; index < source.length; index++) {
		const char = source[index];
		if (quoted) {
			if (char === '"' && source[index + 1] === '"') {
				field += '"';
				index++;
			} else if (char === '"') {
				quoted = false;
			} else {
				field += char;
			}
			continue;
		}
		if (char === '"' && field.length === 0) {
			quoted = true;
		} else if (char === sep) {
			row.push(field);
			field = "";
		} else if (char === "\n") {
			row.push(field);
			rows.push(row);
			row = [];
			field = "";
		} else {
			field += char;
		}
	}
	if (field.length > 0 || row.length > 0) {
		row.push(field);
		rows.push(row);
	}
	return rows;
}

/** `A`, `Z`, `AA`… for a zero-based column index. */
export function columnName(index) {
	let name = "";
	let value = index + 1;
	while (value > 0) {
		const remainder = (value - 1) % 26;
		name = String.fromCharCode(65 + remainder) + name;
		value = Math.floor((value - 1) / 26);
	}
	return name;
}

/** Zero-based column index for `A`, `AA`…; -1 when the reference is invalid. */
export function columnIndex(letters) {
	let value = 0;
	for (const char of letters.toUpperCase()) {
		const digit = char.charCodeAt(0) - 64;
		if (digit < 1 || digit > 26) return -1;
		value = value * 26 + digit;
	}
	return value - 1;
}

/** Whether a CSV field should be written as a number rather than text. */
export function looksNumeric(value) {
	if (!/^-?(?:\d+|\d*\.\d+)(?:[eE][+-]?\d+)?$/.test(value)) return false;
	if (value.startsWith("0") && value !== "0" && !value.startsWith("0.")) return false;
	if (value.startsWith("-0") && value !== "-0" && !value.startsWith("-0.")) return false;
	return value.replace(/[-.]/g, "").length <= 15;
}

/** The maximum number of characters a sheet's cell can hold before truncation. */
function clipCell(value) {
	const text = String(value ?? "");
	return text.length > MAX_CELL_CHARS ? text.slice(0, MAX_CELL_CHARS) : text;
}

function sanitizeSheetName(name) {
	const cleaned = String(name ?? "").replace(/[\[\]:*?/\\]/g, " ").trim().slice(0, 31);
	return cleaned.length === 0 ? "Sheet1" : cleaned;
}

function cellXml(reference, value, style) {
	const s = style === 0 ? "" : ` s="${style}"`;
	if (value.startsWith("=") && value.length > 1) {
		return `<c r="${reference}"${s}><f>${escapeXml(value.slice(1))}</f></c>`;
	}
	if (looksNumeric(value)) {
		return `<c r="${reference}"${s}><v>${value}</v></c>`;
	}
	return `<c r="${reference}"${s} t="inlineStr"><is><t xml:space="preserve">${escapeXml(clipCell(value))}</t></is></c>`;
}

function sheetXml(rows, columns) {
	const widths = Array.from({ length: columns }, (_, column) => {
		let width = 8;
		for (const row of rows) width = Math.max(width, Math.min(50, (row[column] ?? "").length + 2));
		return width;
	});
	const cols = columns === 0 ? "" : `<cols>${widths.map((width, index) =>
		`<col min="${index + 1}" max="${index + 1}" width="${width}" customWidth="1"/>`).join("")}</cols>`;
	const sheetRows = rows.map((row, rowIndex) => {
		const cells = Array.from({ length: columns }, (_, column) =>
			cellXml(`${columnName(column)}${rowIndex + 1}`, row[column] ?? "", rowIndex === 0 && rows.length > 1 ? 1 : 0)).join("");
		return `<row r="${rowIndex + 1}">${cells}</row>`;
	}).join("");
	const dimension = rows.length === 0 || columns === 0
		? "A1"
		: `A1:${columnName(columns - 1)}${rows.length}`;
	return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="${NS_MAIN}" xmlns:r="${NS_R}"><dimension ref="${dimension}"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>${cols}<sheetData>${sheetRows}</sheetData></worksheet>`;
}

const STYLES_XML = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="${NS_MAIN}">
<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts>
<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>
<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
<cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/></cellXfs>
<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>`;

const CONTENT_TYPES = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>
</Types>`;

const ROOT_RELS = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>`;

const WORKBOOK_RELS = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
</Relationships>`;

/**
 * Build a one-sheet .xlsx from CSV/TSV.
 * The first row is bolded and frozen when the sheet has more than one row.
 */
export function buildXlsx(text, options = {}) {
	const rows = parseCsv(text, options.delimiter);
	if (rows.length === 0) throw new OfficeError("cannot build a workbook with no rows", "OFFICE_BAD_ARGS");
	const columns = Math.max(1, ...rows.map((row) => row.length));
	if (columns > MAX_COLS) throw new OfficeError(`too many columns (${columns} > ${MAX_COLS})`, "OFFICE_TOO_LARGE");
	if (rows.length > MAX_ROWS) throw new OfficeError(`too many rows (${rows.length} > ${MAX_ROWS})`, "OFFICE_TOO_LARGE");
	const sheetName = sanitizeSheetName(options.sheetName);
	const workbook = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="${NS_MAIN}" xmlns:r="${NS_R}"><sheets><sheet name="${escapeXml(sheetName)}" sheetId="1" r:id="rId1"/></sheets><calcPr calcId="0" fullCalcOnLoad="1"/></workbook>`;
	const buffer = writeZip([
		{ name: "[Content_Types].xml", data: CONTENT_TYPES },
		{ name: "_rels/.rels", data: ROOT_RELS },
		{ name: "xl/workbook.xml", data: workbook },
		{ name: "xl/_rels/workbook.xml.rels", data: WORKBOOK_RELS },
		{ name: "xl/styles.xml", data: STYLES_XML },
		{ name: "xl/worksheets/sheet1.xml", data: sheetXml(rows, columns) }
	]);
	const formulas = rows.flat().filter((cell) => cell.startsWith("=") && cell.length > 1).length;
	return { buffer, rows: rows.length, columns: columns === 0 ? 0 : columns, sheetName, formulas };
}

/** Decoded workbook sheet metadata. */
class SheetRef {
	constructor(name, target) {
		this.name = name;
		this.target = target;
	}
}

/** Map `<sheet r:id>` to a worksheet part through workbook relationships. */
function workbookSheets(workbookXml, relsXml) {
	const rels = new Map();
	const relPattern = /<Relationship\b[^>]*>/g;
	let relMatch;
	while ((relMatch = relPattern.exec(relsXml ?? "")) !== null) {
		const id = /\bId="([^"]+)"/.exec(relMatch[0]);
		const target = /\bTarget="([^"]+)"/.exec(relMatch[0]);
		const type = /\bType="([^"]+)"/.exec(relMatch[0]);
		if (id === null || target === null) continue;
		if (type !== null && !/\/worksheet$/.test(type[1])) continue;
		rels.set(id[1], target[1]);
	}
	const sheets = [];
	const sheetPattern = /<sheet\b[^>]*>/g;
	let sheetMatch;
	let fallback = 1;
	while ((sheetMatch = sheetPattern.exec(workbookXml)) !== null) {
		const name = /\bname="([^"]*)"/.exec(sheetMatch[0]);
		const rid = /\br:id="([^"]+)"/.exec(sheetMatch[0]) ?? /\bid="([^"]+)"/.exec(sheetMatch[0]);
		const target = rid === null ? undefined : rels.get(rid[1]);
		let part = target;
		if (part === undefined) part = `worksheets/sheet${fallback}.xml`;
		fallback++;
		if (part.startsWith("/")) part = part.slice(1);
		else if (!part.startsWith("xl/")) part = `xl/${part}`;
		sheets.push(new SheetRef(decodeXml(name?.[1] ?? `Sheet${sheets.length + 1}`), part));
	}
	return sheets;
}

/** Read the shared-string table; index order is the cell's `v` value. */
function sharedStrings(xml) {
	if (xml === undefined) return [];
	const values = [];
	const siPattern = /<si>([\s\S]*?)<\/si>/g;
	let match;
	while ((match = siPattern.exec(xml)) !== null) {
		let text = "";
		const tPattern = /<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g;
		let tMatch;
		while ((tMatch = tPattern.exec(match[1])) !== null) text += decodeXml(tMatch[1]);
		values.push(text);
	}
	return values;
}

const BUILTIN_DATE_FORMATS = new Set([14, 15, 16, 17, 18, 19, 20, 21, 22, 45, 46, 47]);

/** Style index → whether it renders as a date, using numFmt ids and formats. */
function dateStyles(stylesXml) {
	if (stylesXml === undefined) return [];
	const custom = new Map();
	const numFmtPattern = /<numFmt\b[^>]*numFmtId="(\d+)"[^>]*formatCode="([^"]*)"[^>]*\/>/g;
	let numFmtMatch;
	while ((numFmtMatch = numFmtPattern.exec(stylesXml)) !== null) {
		custom.set(Number(numFmtMatch[1]), decodeXml(numFmtMatch[2]));
	}
	const xfsMatch = /<cellXfs\b[^>]*>([\s\S]*?)<\/cellXfs>/.exec(stylesXml);
	if (xfsMatch === null) return [];
	const result = [];
	const xfPattern = /<xf\b([^>]*?)\/?>/g;
	let xfMatch;
	while ((xfMatch = xfPattern.exec(xfsMatch[1])) !== null) {
		const numFmtId = Number((/\bnumFmtId="(\d+)"/.exec(xfMatch[1]) ?? [0, "0"])[1]);
		const format = custom.get(numFmtId);
		if (BUILTIN_DATE_FORMATS.has(numFmtId)) result.push(true);
		else if (format !== undefined && /[ymd]/i.test(format) && !/^[#0.,%]+$/.test(format)) result.push(true);
		else result.push(false);
	}
	return result;
}

/** Excel serial date → ISO text; keeps the time when the fraction is non-zero. */
export function serialToIso(serial) {
	if (!Number.isFinite(serial) || serial < 0) return String(serial);
	const whole = Math.floor(serial);
	const fraction = serial - whole;
	// Excel's leap-year bug: serial 1 is 1900-01-01, but serial 61 is
	// 1900-03-01, so the 1899-12-30 epoch only holds from 61 onward. 60 is the
	// non-existent 1900-02-29 and reads as 1900-02-28, like openpyxl.
	const days = whole <= 59 ? whole + 1 : whole;
	const date = new Date(Date.UTC(1899, 11, 30) + days * 86400000);
	if (Number.isNaN(date.getTime())) return String(serial);
	const iso = date.toISOString().slice(0, 10);
	if (fraction <= 0) return iso;
	const seconds = Math.round(fraction * 86400);
	const hours = Math.floor(seconds / 3600);
	const minutes = Math.floor((seconds % 3600) / 60);
	const secs = seconds % 60;
	return `${iso} ${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
}

/** Parse one worksheet into a rectangular (jagged) string matrix. */
function sheetRows(xml, strings, dates) {
	const rows = [];
	const rowPattern = /<row\b([^>]*)>([\s\S]*?)<\/row>/g;
	let rowMatch;
	while ((rowMatch = rowPattern.exec(xml)) !== null) {
		const rowNumber = Number((/\br="(\d+)"/.exec(rowMatch[1]) ?? [0, rows.length + 1])[1]);
		const cells = [];
		const cellPattern = /<c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g;
		let cellMatch;
		while ((cellMatch = cellPattern.exec(rowMatch[2])) !== null) {
			const attrs = cellMatch[1];
			const body = cellMatch[2] ?? "";
			const reference = /\br="([A-Za-z]+)(\d+)"/.exec(attrs);
			const column = reference === null ? cells.length : columnIndex(reference[1]);
			if (column < 0 || column >= MAX_COLS) continue;
			const type = (/\bt="([^"]+)"/.exec(attrs) ?? [0, "n"])[1];
			const style = Number((/\bs="(\d+)"/.exec(attrs) ?? [0, "0"])[1]);
			const formula = /<f(?:\s[^>]*)?>([\s\S]*?)<\/f>/.exec(body);
			const valueMatch = /<v(?:\s[^>]*)?>([\s\S]*?)<\/v>/.exec(body);
			const inline = /<is>([\s\S]*?)<\/is>/.exec(body);
			let value = "";
			if (formula !== null) {
				// Prefer the formula over a cached value: a reader wants to know
				// what the cell computes, and Excel recalculates on load anyway.
				value = `=${decodeXml(formula[1])}`;
			} else if (type === "s" && valueMatch !== null) {
				value = strings[Number(valueMatch[1])] ?? "";
			} else if (type === "inlineStr" && inline !== null) {
				const tPattern = /<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g;
				let tMatch;
				while ((tMatch = tPattern.exec(inline[1])) !== null) value += decodeXml(tMatch[1]);
			} else if (type === "b" && valueMatch !== null) {
				value = valueMatch[1] === "1" ? "TRUE" : "FALSE";
			} else if (type === "str" && valueMatch !== null) {
				value = decodeXml(valueMatch[1]);
			} else if (valueMatch !== null) {
				const raw = decodeXml(valueMatch[1]);
				const numeric = Number(raw);
				if (dates[style] === true && Number.isFinite(numeric)) value = serialToIso(numeric);
				else value = raw;
			}
			cells[column] = clipCell(value);
		}
		for (let index = 0; index < cells.length; index++) {
			if (cells[index] === undefined) cells[index] = "";
		}
		rows[rowNumber - 1] = cells;
	}
	for (let index = 0; index < rows.length; index++) {
		if (rows[index] === undefined) rows[index] = [];
	}
	return rows;
}

/** Render a sheet as TSV with a `## Sheet: name` header. */
function sheetText(name, rows) {
	const lines = [`## Sheet: ${name}`];
	for (const row of rows) lines.push(row.join("\t"));
	return lines.join("\n");
}

/**
 * Read a workbook into `{ sheets, text, truncated }`.
 * `sheet` selects one sheet by name; otherwise every worksheet is returned,
 * capped by `maxChars` for the combined text.
 */
export function readXlsx(input, options = {}) {
	const maxChars = options.maxChars ?? 30000;
	const maxRows = options.maxRows ?? MAX_ROWS;
	const maxCols = options.maxCols ?? MAX_COLS;
	let archive;
	try {
		archive = readZip(input);
	} catch (error) {
		throw new OfficeError(`not a readable .xlsx package: ${error.message}`, "OFFICE_BAD_ZIP");
	}
	const workbook = archive.text("xl/workbook.xml");
	if (workbook === undefined) {
		throw new OfficeError("the package has no xl/workbook.xml (is this a .xlsx?)", "OFFICE_BAD_ZIP");
	}
	const rels = archive.text("xl/_rels/workbook.xml.rels");
	const strings = sharedStrings(archive.text("xl/sharedStrings.xml"));
	const dates = dateStyles(archive.text("xl/styles.xml"));
	const refs = workbookSheets(workbook, rels);
	if (refs.length === 0) throw new OfficeError("the workbook declares no worksheets", "OFFICE_PARSE_FAILED");
	const wanted = typeof options.sheet === "string" && options.sheet.length > 0
		? refs.filter((ref) => ref.name.toLowerCase() === options.sheet.toLowerCase())
		: refs;
	if (wanted.length === 0) {
		throw new OfficeError(`no sheet named "${options.sheet}" (available: ${refs.map((ref) => ref.name).join(", ")})`, "OFFICE_BAD_ARGS");
	}
	const sheets = [];
	let text = "";
	let truncated = false;
	for (const ref of wanted) {
		const xml = archive.text(ref.target);
		if (xml === undefined) continue;
		let rows = sheetRows(xml, strings, dates);
		let sheetTruncated = false;
		if (rows.length > maxRows) {
			rows = rows.slice(0, maxRows);
			sheetTruncated = true;
		}
		if (rows.some((row) => row.length > maxCols)) sheetTruncated = true;
		rows = rows.map((row) => row.length > maxCols ? row.slice(0, maxCols) : row);
		sheets.push({ name: ref.name, rows, truncated: sheetTruncated });
		const piece = sheetText(ref.name, rows);
		if (text.length + piece.length > maxChars) {
			text += piece.slice(0, Math.max(0, maxChars - text.length));
			truncated = true;
			break;
		}
		text += `${text.length === 0 ? "" : "\n\n"}${piece}`;
		if (sheetTruncated) truncated = true;
	}
	return { sheets, text, truncated };
}
